<script setup lang="ts">
import {computed,ref,onBeforeUnmount,onMounted} from 'vue'
import NotebookIcon from './NotebookIcon.vue'
import type {Course,Scope} from '../editor/model'
const props=defineProps<{courses:Course[];scope:Scope;current?:Scope}>()
const emit=defineEmits<{change:[scope:Scope];selectCourse:[id:string]}>()
const picker=ref<'course'|'lesson'|null>(null),query=ref(''),root=ref<HTMLElement>()
const course=computed(()=>props.courses.find(c=>c.id===props.scope.courseId))
const lessons=computed(()=>(course.value?.lessons||[]).filter(l=>!query.value||l.title.includes(query.value)))
const courses=computed(()=>props.courses.filter(c=>!query.value||c.title.includes(query.value)))
function chooseCourse(id:string){emit('change',id==='__plan'?{mode:'PLAN'}:{mode:'COURSE',courseId:id});if(id!=='__plan')emit('selectCourse',id);picker.value=null}
function chooseLesson(id:string){emit('change',id==='__course'?{mode:'COURSE',courseId:props.scope.courseId}:{mode:'LESSON',courseId:props.scope.courseId,lessonId:id});picker.value=null}
function keyboard(event:KeyboardEvent){if(event.key==='Escape'){picker.value=null;return}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...root.value!.querySelectorAll<HTMLButtonElement>('.picker-item')];let at=buttons.indexOf(document.activeElement as HTMLButtonElement);at=event.key==='Home'?0:event.key==='End'?buttons.length-1:(at+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[at]?.focus()}
function outside(e:MouseEvent){if(!root.value?.contains(e.target as Node))picker.value=null}
onMounted(()=>window.addEventListener('click',outside));onBeforeUnmount(()=>window.removeEventListener('click',outside))
</script>
<template><div ref="root" class="scope-bar" :class="{'is-plan-scope':scope.mode==='PLAN'}" @keydown="keyboard"><div class="picker-wrap"><button type="button" class="scope-button" aria-label="课程范围" :aria-expanded="picker==='course'" @click="picker=picker==='course'?null:'course';query=''"><span class="scope-label" :title="scope.mode==='PLAN'?'全计划':course?.title||'当前课程'">{{scope.mode==='PLAN'?'全计划':course?.title||'当前课程'}}</span><NotebookIcon name="chevron"/></button><div v-if="picker==='course'" class="picker-panel"><input v-model="query" aria-label="查找课程" placeholder="查找课程…"><button class="picker-item" @click="chooseCourse('__plan')">全计划</button><button v-for="c in courses" :key="c.id" class="picker-item" :class="{'is-on':scope.courseId===c.id}" @click="chooseCourse(c.id)">{{c.title}}</button></div></div><span v-if="scope.mode!=='PLAN'" class="scope-separator">/</span><div v-if="scope.mode!=='PLAN'" class="picker-wrap"><button type="button" class="scope-button" aria-label="知识点范围" :aria-expanded="picker==='lesson'" @click="picker=picker==='lesson'?null:'lesson';query=''"><span class="scope-label" :title="scope.mode==='COURSE'?'整门课程':course?.lessons.find(l=>l.id===scope.lessonId)?.title||'当前知识点'">{{scope.mode==='COURSE'?'整门课程':course?.lessons.find(l=>l.id===scope.lessonId)?.title||'当前知识点'}}</span><NotebookIcon name="chevron"/></button><div v-if="picker==='lesson'" class="picker-panel"><input v-model="query" aria-label="查找知识点" placeholder="查找知识点…"><button class="picker-item" @click="chooseLesson('__course')">整门课程</button><button v-for="l in lessons" :key="l.id" class="picker-item" :class="{'is-on':scope.lessonId===l.id}" @click="chooseLesson(l.id)">{{l.title}}</button></div></div><button v-if="current" class="follow-button" title="回到当前知识点" aria-label="回到当前知识点" @click="emit('change',current)"><NotebookIcon name="return"/></button><slot/></div></template>
